/**
 * 每个标识在 .pen 里的 16×16 盒内位置与大小，换算成 viewBox。
 * viewBox = [minX, minY, w, h]，由原始路径的 tight bbox 拉伸到节点盒决定，
 * 这里直接用路径自身坐标空间，并通过 transform 对齐到 16×16。
 */
type Shape = { paths: string[]; box: [number, number, number, number]; slot: [number, number, number, number]; evenodd?: boolean }

/** 24×24 的 simple-icons 路径统一居中放进 16×16 盒（与 Trae 的留白一致） */
const VENDOR_BOX: [number, number, number, number] = [0, 0, 24, 24]
const VENDOR_SLOT: [number, number, number, number] = [1, 1, 14, 14]
const vendorShape = (paths: string[], evenodd = false): Shape => ({ paths, box: VENDOR_BOX, slot: VENDOR_SLOT, evenodd })

const SHAPES: Partial<Record<ProviderId, Shape>> = {
  // slot: 在 16×16 图标框内的 x / y / w / h（取自 .pen）
  claude: { paths: [CLAUDE_D], box: [0, 0, 57.6, 57.95], slot: [0.881225, 0.8468, 14.2242, 14.311175] },
  codex: { paths: [CODEX_D], box: [0, 0, 60.76, 64.08], slot: [0.414825, 0, 15.190125, 16] },
  gemini: { paths: [GEMINI_D], box: [0, 0, 57.28, 57.34], slot: [0.832, 0.8, 14.32, 14.336] },
  grok: { paths: [GROK_D1, GROK_D2], box: [0, 0, 53.312, 39.36], slot: [0.8, 3.088, 13.328, 9.84] },
  trae: { paths: [TRAE_D], box: [0, 0, 24, 24], slot: [1, 1, 14, 14] },
  // 厂商预设（供应商页 P4.1）：simple-icons 七家 + lobe-icons 五家，全部有官方图形
  deepseek: vendorShape([DEEPSEEK_D]),
  kimi: vendorShape([KIMI_D]),
  minimax: vendorShape([MINIMAX_D]),
  qwen: vendorShape([QWEN_D]),
  openrouter: vendorShape([OPENROUTER_D]),
  ollama: vendorShape([OLLAMA_D]),
  lmstudio: vendorShape([LMSTUDIO_D]),
  groq: vendorShape([GROQ_D], true),
  stepfun: vendorShape([STEPFUN_D], true),
  together: vendorShape([TOGETHER_D1, TOGETHER_D2, TOGETHER_D3], true),
  fireworks: vendorShape([FIREWORKS_D], true),
  // 硅基流动的图形取自其官方云服务 SiliconCloud 的品牌标识（同一家公司的现行标志）
  siliconflow: vendorShape([SILICONFLOW_D], true),
}

// Grok 第二条路径在 .pen 中有独立偏移，单独换算
const GROK_SECOND_SLOT: [number, number, number, number] = [5.632, 6.416, 9.568, 6.512]
const GROK_SECOND_BOX: [number, number, number, number] = [0, 0, 38.272, 26.048]

// 有官方位图/SVG 资产的平台（复杂插画型 logo 不适合内嵌 path，用资产文件 + img）
const IMAGE_SOURCES: Partial<Record<ProviderId, string>> = {
  qoder: qoderLogo,
  zcode: zcodeLogo,
  workbuddy: workbuddyLogo,
}

const COLOR_CLASS: Partial<Record<ProviderId, string>> = {
  trae: "text-[#32F08C]",
  claude: "text-logo-claude",
  codex: "text-logo-codex",
  gemini: "text-logo-gemini",
  grok: "text-logo-grok",
}

export interface PlatformLogoProps {
  /** 平台 id 或厂商预设 id（deepseek / kimi / …）；未知 id 回落首字母圆标 */
  platform: ProviderId
  /** 默认 16px，与 .pen 中的 C/Logo * 组件一致 */
  size?: number
  className?: string
}

export function PlatformLogo({ platform, size = 16, className }: PlatformLogoProps) {
  // 官方资产优先：Qoder / ZCode / WorkBuddy 用官网下载的图标文件
  const imageSrc = IMAGE_SOURCES[platform]
  if (imageSrc) {
    return (
      <img
        src={imageSrc}
        width={size}
        height={size}
        alt={platform}
        className={cn("shrink-0 object-contain", className)}
      />
    )
  }

  // 自定义供应商：与 Skills 供应商菜单（skillParts）同一个六边形 + 代码标识，不是品牌图形
  if (platform === "custom") {
    return (
      <span
        role="img"
        aria-label="自定义供应商"
        style={{ width: size, height: size, borderRadius: size * 0.27 }}
        className={cn("relative grid shrink-0 place-items-center bg-jolu-selected text-jolu-on", className)}
      >
        <Hexagon aria-hidden style={{ width: size * 0.8, height: size * 0.8 }} className="absolute" />
        <Code aria-hidden style={{ width: size * 0.5, height: size * 0.5 }} />
      </span>
    )
  }

  // OpenCode：Jolu.pen 用「OC」缩写标记（12 / 700，前景色），不是官方图形
  if (platform === "opencode") {
    return (
      <svg width={size} height={size} viewBox="0 0 16 16" className={cn("shrink-0", className)} aria-label="OpenCode" role="img">
        <text x="8" y="8.6" dominantBaseline="middle" textAnchor="middle" fontSize="8.6" fontWeight="700" fill="currentColor" className="text-jolu-text">OC</text>
      </svg>
    )
  }

  const shape = SHAPES[platform]
  const k = size / 16

  // 暂无官方路径的平台：首字母圆标（颜色用主题前景，不假冒品牌）
  if (!shape) {
    const letter = platform.charAt(0).toUpperCase()
    return (
      <svg
        width={size}
        height={size}
        viewBox={`0 0 ${size} ${size}`}
        className={cn("shrink-0", className)}
        aria-label={platform}
        role="img"
      >
        <circle cx={size / 2} cy={size / 2} r={size / 2} className="fill-surface-3" />
        <text
          x="50%"
          y="54%"
          dominantBaseline="middle"
          textAnchor="middle"
          fontSize={size * 0.5}
          fontWeight="700"
          className="fill-text-secondary"
        >
          {letter}
        </text>
      </svg>
    )
  }

  const renderPath = (
    d: string,
    slot: [number, number, number, number],
    box: [number, number, number, number],
    key: number,
    evenodd?: boolean,
  ) => {
    const [sx, sy, sw, sh] = slot
    const [, , bw, bh] = box
    const scaleX = (sw * k) / bw
    const scaleY = (sh * k) / bh
    return (
      <path
        key={key}
        d={d}
        transform={`translate(${sx * k} ${sy * k}) scale(${scaleX} ${scaleY})`}
        fill="currentColor"
        fillRule={evenodd ? "evenodd" : undefined}
      />
    )
  }

  return (
    <svg
      width={size}
      height={size}
      viewBox={`0 0 ${size} ${size}`}
      className={cn("shrink-0", COLOR_CLASS[platform], className)}
      aria-label={platform}
      role="img"
    >
      {platform === "grok"
        ? [
            renderPath(GROK_D1, shape.slot, shape.box, 0),
            renderPath(GROK_D2, GROK_SECOND_SLOT, GROK_SECOND_BOX, 1),
          ]
        : shape.paths.map((d, i) => renderPath(d, shape.slot, shape.box, i, shape.evenodd))}
    </svg>
  )
}
